nextflow_process {

    name "Test Process SCIMAP_SPATIALLDA"
    script "../main.nf"
    config "./nextflow.config"
    process "SCIMAP_SPATIALLDA"

    tag "modules"
    tag "modules_nfcore"
    tag "scimap"
    tag "scimap/spatiallda"

    test("spatiallda - csv") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'imaging/downstream/phenotyped.csv', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["motif_location_plot"])
                ).match() },
                { assert path(process.out.motif_location_plot[0][1]).exists() }
            )
        }
    }
    test("spatiallda - stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'imaging/downstream/phenotyped.csv', checkIfExists: true)
                ]
                """
            }
        }
        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

process {
    withName: "SCIMAP_SPATIALLDA" {
        ext.args = '--phenotype phenotype --x-coordinate X_centroid --y-coordinate Y_centroid --sample-id sampleid --radius 30 --num-motifs 10 --method radius'
    }
}
